FUNCTION_BLOCK FB_S08
VAR_INPUT
    RecipeSelect : INT;
    ChangeoverReq : BOOL;
    PartHeight : REAL;
    EStop_NC : BOOL;
END_VAR
VAR_OUTPUT
    ActiveRecipe : INT := 1;
    SortLeft : BOOL := FALSE;
    SortRight : BOOL := FALSE;
    Busy : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    ChangeoverReqLast : BOOL := FALSE;
    ChangeoverRise : BOOL;
    StartupScans : INT := 0;
    BusyScans : INT := 0;
    BusyAtScanStart : BOOL;
    RecipeValid : BOOL;
    LeftThreshold : REAL;
    RightThreshold : REAL;
END_VAR

(*
    扫描周期：20 ms。

    待审语义冲突：
    C9 原文：G(Busy -> G[0,100](Busy))。
    该公式从每个 Busy 周期重新要求未来 100 周期保持 Busy，
    因而一旦 Busy 为 TRUE，便不能再清除；与需求中的
    “保持 2 s 后自动清除”矛盾。
    本实现采用需求中的有限 2 s 保持，不声称满足原 C9。

    C10 原文：
    G[0,1](!SortLeft && !SortRight && !Busy && ActiveRecipe == 1)。
    按闭区间解释，前两个调用保持上电状态，期间请求边沿不排队。

    边界待审：
    等于右阈值既不属于右分拣区间，也不属于“超过右阈值”。
    按原文严格比较：等于右阈值时不分拣、不报超规格。

    EStop_NC 未指定复位或状态码语义：
    此处仅采用安全抑制，急停时禁止分拣及接受新切换；
    已开始的切换计时继续，不改变 ActiveRecipe。

    K4 的“同一产品”缺少产品身份或通过检测接口；
    本实现保证逐扫描互斥，不声称验证跨扫描产品身份一致性。
    未提供编译或逐周期测试证据。
*)

ChangeoverRise := ChangeoverReq AND NOT ChangeoverReqLast;
ChangeoverReqLast := ChangeoverReq;

RecipeValid := (RecipeSelect >= 1) AND (RecipeSelect <= 3);

SortLeft := FALSE;
SortRight := FALSE;
Status := WORD#16#0000;

IF NOT RecipeValid THEN
    Status := WORD#16#8801;
END_IF;

IF StartupScans < 2 THEN
    ActiveRecipe := 1;
    Busy := FALSE;
    BusyScans := 0;
    StartupScans := StartupScans + 1;
ELSE
    BusyAtScanStart := Busy;

    (* 接受切换的扫描为计时起点；100 个后续扫描为 2 s。 *)
    IF BusyAtScanStart THEN
        IF BusyScans < 100 THEN
            BusyScans := BusyScans + 1;
        END_IF;

        IF BusyScans >= 100 THEN
            Busy := FALSE;
            BusyScans := 0;
        END_IF;
    END_IF;

    (* 扫描开始时仍忙的请求不在本扫描到期后重新接受。 *)
    IF EStop_NC
       AND ChangeoverRise
       AND NOT BusyAtScanStart
       AND RecipeValid
       AND (PartHeight = 0.0) THEN
        ActiveRecipe := RecipeSelect;
        Busy := TRUE;
        BusyScans := 0;
    END_IF;

    CASE ActiveRecipe OF
        1:
            LeftThreshold := 30.0;
            RightThreshold := 60.0;
        2:
            LeftThreshold := 50.0;
            RightThreshold := 90.0;
        3:
            LeftThreshold := 70.0;
            RightThreshold := 120.0;
    ELSE
        (* 内部状态异常时禁止动作，不自行恢复到其他配方。 *)
        LeftThreshold := 0.0;
        RightThreshold := 0.0;
    END_CASE;

    IF EStop_NC
       AND NOT Busy
       AND (ActiveRecipe >= 1)
       AND (ActiveRecipe <= 3)
       AND (PartHeight > 0.0) THEN

        IF PartHeight < LeftThreshold THEN
            SortLeft := TRUE;
        ELSIF PartHeight < RightThreshold THEN
            SortRight := TRUE;
        ELSIF PartHeight > RightThreshold THEN
            (* 非法选择错误优先，保留 K3 的状态码。 *)
            IF RecipeValid THEN
                Status := WORD#16#8802;
            END_IF;
        END_IF;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
